_GraftPlan.source:
class _GraftPlan(dict):
    def __deepcopy__(self, memo):
        import copy
        result = type(self)()
        memo[id(self)] = result
        for key, value in self.items():
            result[key] = value if key == "layouts" else copy.deepcopy(value, memo)
        return result

